package com.flippingfriend.companion;
import java.util.ArrayList; import java.util.List;
/** Pure fail-closed sell-fill interpretation using the shared plausibility contract. */
final class BuyReplacementSellFillViabilityEvaluator {
 BuyReplacementSellFillViabilityAssessment evaluate(BuyReplacementSellFillEvaluationSet s,long at){if(s==null||at<s.getEvaluatedAt()||s.getEvaluatedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getEvaluations()==null||s.getEvaluations().isEmpty()||s.getCandidates()==null||s.getCandidates().size()!=s.getEvaluations().size())return null;List<BuyReplacementSellFillEvaluation> complete=new ArrayList<>(s.getEvaluations().size());List<BuyReplacementSellFillViableCandidate> viable=new ArrayList<>();for(int i=0;i<s.getEvaluations().size();i++){BuyReplacementSellFillEvaluation e=s.getEvaluations().get(i);BuyReplacementPositiveNetMarginCandidate c=s.getCandidates().get(i);if(!valid(e,c,s))return null;complete.add(e);if(e.getSellProbability()>0&&Double.isFinite(e.getSellExpectedHours()))viable.add(new BuyReplacementSellFillViableCandidate(e));}return new BuyReplacementSellFillViabilityAssessment(s,viable.isEmpty()?BuyReplacementSellFillViabilityOutcome.NOT_VIABLE:BuyReplacementSellFillViabilityOutcome.VIABLE,complete,viable,at);}
 private static boolean valid(BuyReplacementSellFillEvaluation e,BuyReplacementPositiveNetMarginCandidate c,BuyReplacementSellFillEvaluationSet s){return e!=null&&c!=null&&e.getBuyOffsetIndex()==c.getBuyOffsetIndex()&&Double.compare(e.getBuyOffset(),c.getBuyOffset())==0&&e.getBuyPrice()==c.getBuyPrice()&&e.getExactRemainderQuantity()==s.getExactRemainderQuantity()&&e.getExactRemainderQuantity()==c.getExactRemainderQuantity()&&e.getTotalCost()==c.getTotalCost()&&Double.compare(e.getBuyProbability(),c.getBuyProbability())==0&&Double.compare(e.getBuyExpectedHours(),c.getBuyExpectedHours())==0&&Double.compare(e.getBuyUnitsPerHour(),c.getBuyUnitsPerHour())==0&&Double.compare(e.getBuyWaitHours(),c.getBuyWaitHours())==0&&e.getSellOffsetIndex()==c.getSellOffsetIndex()&&Double.compare(e.getSellOffset(),c.getSellOffset())==0&&e.getSellPrice()==c.getSellPrice()&&e.getRawSpreadPerItem()==c.getRawSpreadPerItem()&&e.getTaxPerItem()==c.getTaxPerItem()&&e.getNetMarginPerItem()==c.getNetMarginPerItem()&&e.getTotalTax()==c.getTotalTax()&&e.getTotalNetMargin()==c.getTotalNetMargin()&&Double.isFinite(e.getSellProbability())&&e.getSellProbability()>=0&&e.getSellProbability()<=1&&!Double.isNaN(e.getSellExpectedHours())&&e.getSellExpectedHours()>=0&&Double.isFinite(e.getSellUnitsPerHour())&&e.getSellUnitsPerHour()>=0&&!Double.isNaN(e.getSellWaitHours())&&e.getSellWaitHours()>=0;}
}
